use std::{env,fs};
fn between<'a>(s:&'a str,a:&str,b:&str)->&'a str{let p=s.find(a).unwrap()+a.len();let q=s[p..].find(b).unwrap()+p;&s[p..q]}
fn nums(s:&str,name:&str)->Vec<u64>{let body=between(s,&format!("{name} = {{"),"};");if body.trim().is_empty(){return vec![]}body.split(',').map(|x|{let x=x.trim();if let Some(h)=x.strip_prefix("0x"){u64::from_str_radix(h,16).unwrap()}else{x.parse().unwrap()}}).collect()}
fn main(){let mut args=env::args().skip(1);let p=args.next().expect("NativeIslandData.as");let prefix=args.next().unwrap_or_else(||"OLD_PHYSICS".into());let s=fs::read_to_string(p).unwrap();let pat=between(&s,&format!("{prefix}_ISLAND_BYTES = \""),"\";");let mut b=Vec::new();for x in pat.split_whitespace(){b.push(u8::from_str_radix(x,16).unwrap())}let ro=nums(&s,&format!("{prefix}_RELOC_OFFSETS"));let rt=nums(&s,&format!("{prefix}_RELOC_TARGET_RVAS"));let rb=between(&s,&format!("{prefix}_RELOC_TARGET_IS_ISLAND = {{"),"};").split(',').filter(|x|!x.trim().is_empty()).map(|x|x.trim()=="true").collect::<Vec<_>>();let ao=nums(&s,&format!("{prefix}_ABS64_OFFSETS"));let at=nums(&s,&format!("{prefix}_ABS64_TARGET_RVAS"));assert_eq!(ro.len(),rt.len());assert_eq!(ro.len(),rb.len());assert_eq!(ao.len(),at.len());let ib=0x0000_0180_0000_0000u64;let mb=0x0000_0001_4000_0000u64;for i in 0..ao.len(){let o=ao[i]as usize;assert!(o+8<=b.len());b[o..o+8].copy_from_slice(&(mb+at[i]).to_le_bytes());}for i in 0..ro.len(){let o=ro[i]as usize;assert!(o+4<=b.len());let target=if rb[i]{assert!((rt[i]as usize)<b.len());ib+rt[i]}else{mb+rt[i]};let d=target as i128-(ib+ro[i]+4)as i128;assert!(d>=i32::MIN as i128&&d<=i32::MAX as i128,"rel32 out of range at {i}");b[o..o+4].copy_from_slice(&(d as i32).to_le_bytes());let got=i32::from_le_bytes(b[o..o+4].try_into().unwrap())as i64;assert_eq!((ib+o as u64+4).wrapping_add_signed(got),target);}if let Some(out)=args.next(){fs::write(out,&b).unwrap();}println!("verified bytes={} rel32={} island_rel32={} image_rel32={} abs64_thunks={}",b.len(),ro.len(),rb.iter().filter(|x|**x).count(),rb.iter().filter(|x|!**x).count(),ao.len());}
